        "html": "<section class=\"section detail-work\"><div class=\"ui-blockcontainer container ui-container\"><div class=\"title-work-wrap\"><div class=\"heading-h1 color-white\">LUMA HEALTH</div></div></div><img src=\"/assets/images/6a57081913127724314f2b6f-d6073aa-235849.webp\" loading=\"lazy\" alt=\"\" sizes=\"100vw\" srcset=\"/assets/images/6a57081913127724314f2b6f-d6073aa-p-500-d0ba8d.webp 500w, /assets/images/6a57081913127724314f2b6f-d6073aa-p-800-fb535f.webp 800w, /assets/images/6a57081913127724314f2b6f-d6073aa-235849.webp 1024w\" class=\"image-hero-work\"/><div class=\"bg-cover-image-work\"></div></section>"
